```javascript
// steps/api/auth/logout-device.step.js
exports.config = {
  type: 'api',
  method: 'POST',
  path: '/auth/sessions/:sessionId/revoke',
  middleware: ['authMiddleware']
}

exports.handler = async (req, { state }) => {
