## Health Checks & Monitoring

```typescript
// steps/monitoring/health-check.step.ts
import { ApiRouteConfig, Handlers } from 'motia'
import { z } from 'zod'

export const config: ApiRouteConfig = {
  type: 'api',
  name: 'HealthCheck',
  description: 'Application health check endpoint',
  method: 'GET',
  path: '/health',
  responseSchema: {
    200: z.object({
      status: z.string(),
      timestamp: z.string(),
      uptime: z.number(),
      version: z.string(),
      environment: z.string(),
      services: z.record(z.object({
        status: z.enum(['healthy', 'unhealthy', 'degraded']),
        responseTime: z.number().optional(),
        error: z.string().optional()
      }))
    }),
    503: z.object({
      status: z.string(),
      error: z.string()
    })
  },
  emits: [],
  flows: ['monitoring']
}

export const handler: Handlers['HealthCheck'] = async (req, { logger, state }) => {
  try {
    const startTime = Date.now()
    const services: Record<string, any> = {}

    // Check database connectivity
    try {
      const dbStart = Date.now()
      await state.get('health', 'db-check')
      services.database = {
        status: 'healthy',
        responseTime: Date.now() - dbStart
      }
    } catch (error) {
      services.database = {
        status: 'unhealthy',
        error: error.message
      }
    }

    // Check Redis connectivity
    try {
      const redisStart = Date.now()
      await checkRedisHealth()
      services.redis = {
        status: 'healthy',
        responseTime: Date.now() - redisStart
      }
    } catch (error) {
      services.redis = {
        status: 'unhealthy',
        error: error.message
      }
    }

    // Check external services
    services.openai = await checkOpenAIHealth()
    services.email = await checkEmailServiceHealth()

    const allHealthy = Object.values(services).every(
      (service: any) => service.status === 'healthy'
    )

    const healthStatus = {
      status: allHealthy ? 'healthy' : 'degraded',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      version: process.env.npm_package_version || '1.0.0',
      environment: process.env.NODE_ENV || 'unknown',
      services
    }

    if (!allHealthy) {
      logger.warn('Health check showing degraded status', { services })
    }

    return {
      status: allHealthy ? 200 : 503,
      body: healthStatus
    }
  } catch (error) {
    logger.error('Health check failed', { error: error.message })
    return {
      status: 503,
      body: {
        status: 'unhealthy',
        error: error.message
      }
    }
  }
}

